import {REGIONS,MAPS,TERRAINS,UNIT_TYPES,getMap,getTerritories,createGame,ownedIds,enemiesOf,placeTroops,attackRound,blitz,fortify,setPhase,endTurn,aiTurn,validateState,canPlayerAttack,tradeCards} from './engine.mjs';

const $=s=>document.querySelector(s),els={map:$('#map'),players:$('#players'),regions:$('#regions'),round:$('#round'),phaseTitle:$('#phaseTitle'),turnLabel:$('#turnLabel'),reinforcements:$('#reinforcements'),reinforceBox:$('#reinforceBox'),orderTitle:$('#orderTitle'),orderText:$('#orderText'),turnStatus:$('#turnStatus'),cardsBox:$('#cardsBox'),terrainPanel:$('#terrainPanel'),selection:$('#selectionInfo'),battle:$('#battleResult'),controls:$('#actionControls'),phaseBtn:$('#phaseBtn'),log:$('#log'),startModal:$('#startModal'),helpModal:$('#helpModal'),diceModal:$('#diceModal'),aiModal:$('#aiModal'),mapGuide:$('#mapGuide'),mapTooltip:$('#mapTooltip'),mapName:$('#mapName'),modeBadge:$('#modeBadge'),routesBtn:$('#routesBtn'),toast:$('#toast')};
let state=null,difficulty='normal',selectedFrom=null,selectedTo=null,selectedDice=3,selectedUnit='infantry',toastTimer=null,aiBusy=false,rolling=false,routesAll=false,hoverId=null,aiTimer=null,aiResolve=null;
const SAVE='fronteras-acero-save-v3';
const ts=()=>state?getTerritories(state):MAPS.frontier.territories,tById=id=>ts().find(t=>t.id===id);
const regionShort=k=>({north:'NORTE',west:'OESTE',crown:'CORONA',ember:'BRASA',sun:'SOL',isles:'JADE'}[k]);
function save(){if(state)localStorage.setItem(SAVE,JSON.stringify({state,difficulty}))}
function load(){try{const d=JSON.parse(localStorage.getItem(SAVE));if(!d?.state||d.state.version!==3||validateState(d.state).length)return false;state=d.state;difficulty=d.difficulty||'normal';return true}catch{return false}}
function showToast(msg){els.toast.textContent=msg;els.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>els.toast.classList.remove('show'),2500)}

function initMap(mapId='frontier'){
  const map=MAPS[mapId]||MAPS.frontier,T=map.territories;els.map.innerHTML=`<image class="map-art" href="./map-${map.id}.webp" x="0" y="0" width="1000" height="760" preserveAspectRatio="xMidYMid slice"/><rect class="map-art-shade" x="0" y="0" width="1000" height="760"/>`;
  const drawn=new Set();for(const t of T)for(const n of t.n){const k=[t.id,n].sort().join('-');if(drawn.has(k))continue;drawn.add(k);const b=T.find(x=>x.id===n),cross=t.region!==b.region?' cross':'';els.map.insertAdjacentHTML('beforeend',`<line class="connection${cross}" data-a="${t.id}" data-b="${n}" x1="${t.x*10}" y1="${t.y*8}" x2="${b.x*10}" y2="${b.y*8}"/>`)}
  for(const t of T){const x=t.x*10,y=t.y*8,r=48,points=Array.from({length:8},(_,i)=>{const a=Math.PI*2*i/8+.18,rr=r*(i%2?1:.88);return`${x+Math.cos(a)*rr},${y+Math.sin(a)*rr}`}).join(' ');els.map.insertAdjacentHTML('beforeend',`<g class="territory" id="terr-${t.id}" data-id="${t.id}" tabindex="0" role="button"><polygon class="territory-shape" points="${points}" style="--region:${REGIONS[t.region].color}44"/><text class="territory-region" x="${x}" y="${y-25}">${regionShort(t.region)}</text><text class="territory-label" x="${x}" y="${y-7}">${t.name}</text><text class="terrain-mark" x="${x-35}" y="${y+24}">${TERRAINS[t.terrain].icon}</text><rect class="army-disc" x="${x-24}" y="${y+3}" width="48" height="31" rx="16"/><text class="unit-mark" x="${x-8}" y="${y+25}">♟</text><text class="army-count" x="${x+11}" y="${y+25}">1</text></g>`)}
  els.map.onclick=e=>{const g=e.target.closest('.territory');if(g)territoryClick(g.dataset.id,e.shiftKey)};els.map.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('.territory')){e.preventDefault();territoryClick(e.target.closest('.territory').dataset.id)}};els.map.onpointerover=e=>{const g=e.target.closest('.territory');if(g){hoverId=g.dataset.id;updateHover(g.dataset.id,e)}};els.map.onpointermove=e=>{if(hoverId)positionTooltip(e)};els.map.onpointerout=e=>{if(e.target.closest('.territory')&&!e.relatedTarget?.closest?.('.territory')){hoverId=null;els.mapTooltip.classList.add('hidden');renderMap()}};els.mapName.textContent=map.name;updateConnections();
}
function positionTooltip(e){const box=document.querySelector('.map-wrap').getBoundingClientRect();els.mapTooltip.style.left=`${Math.min(e.clientX-box.left+14,box.width-230)}px`;els.mapTooltip.style.top=`${Math.max(90,e.clientY-box.top-70)}px`}
function updateHover(id,e){if(!state)return;const t=tById(id),d=state.territories[id],p=state.players[d.owner],terrain=TERRAINS[t.terrain],unit=UNIT_TYPES[d.unitType];els.mapTooltip.innerHTML=`<b>${t.name}</b><div class="tip-row"><span>Propietario</span><strong style="color:${p.color}">${p.name}</strong></div><div class="tip-row"><span>Tropas</span><strong>${d.troops}</strong></div>${state.rulesMode==='terrain'?`<div class="tip-row"><span>Terreno</span><strong>${terrain.icon} ${terrain.name}</strong></div><div class="tip-row"><span>Unidad</span><strong>${unit.icon} ${unit.name}</strong></div>`:''}<div class="tip-adj">Conecta con ${t.n.length} territorios</div>`;els.mapTooltip.classList.remove('hidden');positionTooltip(e);renderMap()}
function updateConnections(){document.querySelectorAll('.connection').forEach(l=>{const related=selectedFrom&&(l.dataset.a===selectedFrom||l.dataset.b===selectedFrom),hovered=hoverId&&(l.dataset.a===hoverId||l.dataset.b===hoverId);l.classList.toggle('visible',!!(related||hovered));l.classList.toggle('show-all',routesAll)});els.routesBtn.textContent=routesAll?'Rutas: todas':'Rutas: al seleccionar';els.routesBtn.setAttribute('aria-pressed',String(routesAll))}

function render(){if(!state)return;const p=state.players[state.current];els.round.textContent=state.turn;els.reinforcements.textContent=state.pendingReinforcements;els.reinforceBox.style.display=state.phase==='reinforce'?'block':'none';els.turnLabel.textContent=p.human?'TU TURNO':`TURNO DE ${p.name.toUpperCase()}`;els.mapName.textContent=getMap(state).name;els.modeBadge.textContent=state.rulesMode==='terrain'?'TERRENO':'CLÁSICO';renderFlow();renderPlayers();renderRegions();renderMap();renderGuide();renderPanel();renderLog();save()}
function renderFlow(){const order=['reinforce','attack','fortify','close'],idx=state.phase==='gameover'?4:Math.max(0,order.indexOf(state.phase));document.querySelectorAll('.flow-step').forEach((el,i)=>{el.classList.toggle('active',i===idx);el.classList.toggle('done',i<idx)})}
function renderPlayers(){els.players.innerHTML=state.players.map(p=>{const ids=ownedIds(state,p.id),troops=ids.reduce((s,id)=>s+state.territories[id].troops,0);return`<div class="player ${state.current===p.id?'active':''} ${!p.alive?'eliminated':''}" style="--pc:${p.color}"><div class="player-top"><i class="player-color"></i><span class="player-name">${p.name}</span>${state.current===p.id&&p.alive?'<span class="turn-badge">EN TURNO</span>':''}</div><div class="player-stats"><span><strong>${ids.length}</strong> territorios</span><span><strong>${troops}</strong> tropas</span><span><strong>${p.cards}</strong> cartas</span></div></div>`}).join('')}
function renderRegions(){els.regions.innerHTML=Object.entries(REGIONS).map(([k,r])=>{const owner=state.players.find(p=>ts().filter(t=>t.region===k).every(t=>state.territories[t.id].owner===p.id));return`<div class="region-row" style="--rc:${r.color}"><i class="region-swatch"></i><span>${r.name}${owner?` · ${owner.name}`:''}</span><strong>+${r.bonus}</strong></div>`}).join('')}
function renderMap(){for(const t of ts()){const d=state.territories[t.id],p=state.players[d.owner],g=$(`#terr-${t.id}`);if(!g)continue;g.style.setProperty('--owner',p.color);g.style.setProperty('--terrain',TERRAINS[t.terrain].color);g.style.setProperty('--unit',UNIT_TYPES[d.unitType].color);g.classList.toggle('owned',d.owner===state.current);g.classList.toggle('selected',t.id===selectedFrom||t.id===selectedTo);g.classList.toggle('target',selectedFrom&&state.phase==='attack'&&enemiesOf(state,selectedFrom).includes(t.id));g.classList.toggle('dimmed',!!hoverId&&hoverId!==t.id&&!t.n.includes(hoverId));g.querySelector('.army-count').textContent=d.troops;g.querySelector('.unit-mark').textContent=state.rulesMode==='terrain'?UNIT_TYPES[d.unitType].icon:'♟';g.querySelector('.terrain-mark').style.display=state.rulesMode==='terrain'?'block':'none';g.setAttribute('aria-label',`${t.name}, ${d.troops} tropas, ${p.name}${state.rulesMode==='terrain'?`, ${TERRAINS[t.terrain].name}, ${UNIT_TYPES[d.unitType].name}`:''}`)}updateConnections()}
function renderLog(){els.log.innerHTML=state.log.slice(0,8).map(l=>`<div class="log-item" style="--lc:${l.p===null?'#788896':state.players[l.p]?.color||'#788896'}"><i class="log-dot"></i><span>${l.text}</span></div>`).join('')}
function setGuide(step,title,text){els.mapGuide.innerHTML=`<span>${step}</span><strong>${title}</strong><small>${text}</small>`}
function renderGuide(){if(!state.players[state.current].human){setGuide('…',`${state.players[state.current].name} está jugando`,'Al terminar verás un informe de sus combates.');return}if(state.phase==='reinforce')setGuide('1','Pulsa tus territorios luminosos',`Coloca las ${state.pendingReinforcements} tropas restantes.`);else if(state.phase==='attack'&&!selectedFrom)setGuide('1','Elige el territorio atacante','Al pasar el cursor solo se iluminan sus rutas reales.');else if(state.phase==='attack'&&!selectedTo)setGuide('2','Elige un vecino enemigo','Los objetivos válidos tienen borde rojo.');else if(state.phase==='attack')setGuide('3','Configura y lanza los dados',state.rulesMode==='terrain'?'La ventaja de unidad o terreno suma +1 al dado mayor.':'El modo clásico no aplica modificadores.');else if(state.phase==='fortify'&&!selectedFrom)setGuide('1','Elige el origen de la maniobra','Debe tener al menos 2 tropas. También puedes pasar.');else if(state.phase==='fortify'&&!selectedTo)setGuide('2','Elige el destino propio','Puede conectarse por una ruta continua propia.');else if(state.phase==='fortify')setGuide('3','Confirma cuántas tropas mover','Siempre quedará al menos una en el origen.');else setGuide('4','Revisa el cierre',state.conqueredThisTurn?'Recibirás una carta.':'No conquistaste: no recibes carta.')}

function renderCards(){const p=state.players[state.current];if(!p.human){els.cardsBox.innerHTML=`<span>Cartas de ${p.name}</span><strong>${p.cards}</strong>`;return}const can=state.phase==='reinforce'&&p.cards>=3,forced=p.cards>=5;els.cardsBox.innerHTML=`<span>🂠 <strong>${p.cards}</strong> cartas ${forced?'<em>· obligatorio</em>':''}</span><button id="tradeBtn" ${can?'':'disabled'}>${can?'Canjear 3':'Necesitas 3'}</button>`;$('#tradeBtn').onclick=()=>{const r=tradeCards(state);if(r.ok){showToast(`Canje completado: +${r.bonus} tropas`);render()}}}
function bonusPreview(from,to){if(state.rulesMode!=='terrain'||!from||!to)return'';const a=state.territories[from],d=state.territories[to],terrain=TERRAINS[tById(to).terrain],au=UNIT_TYPES[a.unitType],du=UNIT_TYPES[d.unitType],aAdv=au.beats===d.unitType,dAdv=du.beats===a.unitType||terrain.unit===d.unitType;return`<div class="bonus-note">${aAdv?`⚔ Atacante: +1 (${au.name} tiene ventaja).`:'Atacante: sin bono.'}<br>${dAdv?`🛡 Defensor: +1 (${terrain.unit===d.unitType?'afinidad de terreno':'ventaja de unidad'}).`:'Defensor: sin bono.'}</div>`}
function renderTerrainPanel(){if(state.rulesMode!=='terrain'){els.terrainPanel.classList.add('hidden');return}els.terrainPanel.classList.remove('hidden');const canChoose=state.phase==='reinforce'&&state.players[state.current].human;els.terrainPanel.innerHTML=`<h3>Rueda de ventaja · +1 al dado mayor</h3><div class="unit-wheel"><b>◆ Infantería</b> vence a <b>✦ Artillería</b> vence a <b>♞ Caballería</b> vence a <b>◆ Infantería</b></div>${canChoose?`<div class="unit-selector">${Object.entries(UNIT_TYPES).map(([k,u])=>`<button data-unit="${k}" class="${selectedUnit===k?'active':''}" style="--unit-color:${u.color}">${u.icon} ${u.name}</button>`).join('')}</div><div class="bonus-note">La unidad elegida se asignará al territorio que refuerces. Bosque favorece Infantería; Montaña, Artillería; Llanura, Caballería.</div>`:bonusPreview(selectedFrom,selectedTo)}`;document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{selectedUnit=b.dataset.unit;renderTerrainPanel()})}
function renderPanel(){const human=state.players[state.current].human;els.battle.innerHTML='';els.controls.innerHTML='';els.selection.innerHTML='';renderCards();renderTerrainPanel();if(state.phase==='gameover'){const won=state.winner===0;els.phaseTitle.textContent=won?'Victoria total':'Campaña terminada';els.orderTitle.textContent=won?'El mapa es tuyo':'Has sido derrotado';els.orderText.textContent=won?'Todos los estandartes enemigos han caído.':'Tus últimos territorios fueron conquistados.';els.turnStatus.innerHTML=won?'<strong>Objetivo cumplido.</strong> Controlas todos los territorios.':'Puedes iniciar otra campaña.';els.phaseBtn.textContent='Nueva partida';els.phaseBtn.disabled=false;return}if(!human){els.phaseTitle.textContent='Turno enemigo';els.orderTitle.textContent=`${state.players[state.current].name} está actuando`;els.orderText.textContent='Al terminar se mostrará un resumen de refuerzos, combates y conquistas.';els.turnStatus.innerHTML='<strong>Espera:</strong> tu turno comenzará automáticamente.';els.phaseBtn.textContent='Procesando…';els.phaseBtn.disabled=true;return}els.phaseBtn.disabled=false;
  if(state.phase==='reinforce'){const forced=state.players[state.current].cards>=5;els.phaseTitle.textContent='Paso 1 · Reclutamiento';els.orderTitle.textContent=forced?'Canje obligatorio':`${state.pendingReinforcements} tropas por desplegar`;els.orderText.textContent=forced?'Canjea un trío antes de colocar tropas.':state.rulesMode==='terrain'?`Unidad elegida: ${UNIT_TYPES[selectedUnit].name}. Pulsa un territorio propio.`:'Pulsa un territorio propio para añadir tropas.';els.turnStatus.innerHTML='<strong>Objetivo:</strong> coloca todas las tropas; después comienza el combate.';els.phaseBtn.textContent=forced?'Canjea cartas':'Coloca todos los refuerzos';els.phaseBtn.disabled=true}
  else if(state.phase==='attack'){const possible=canPlayerAttack(state);els.phaseTitle.textContent='Paso 2 · Combate';els.orderTitle.textContent=selectedTo?'Ataque preparado':selectedFrom?'Elige el objetivo':'Declara un ataque';els.orderText.textContent='Origen propio → ruta iluminada → enemigo → dados → resultado.';els.turnStatus.innerHTML=state.attackMadeThisTurn?'<strong>Tirada obligatoria cumplida.</strong> Puedes seguir o pasar.':possible?'<strong>Ataque obligatorio pendiente.</strong> Resuelve una tirada.':'<strong>Sin ataques legales.</strong> Puedes continuar.';els.phaseBtn.textContent=state.attackMadeThisTurn||!possible?'Finalizar combate →':'Debes atacar';els.phaseBtn.disabled=possible&&!state.attackMadeThisTurn;if(selectedFrom){const a=state.territories[selectedFrom];els.selection.innerHTML=`<div class="selection-item"><span>Origen · ${tById(selectedFrom).name}</span><strong>${a.troops} tropas</strong></div>`}if(selectedTo)renderAttackControls()}
  else if(state.phase==='fortify'){els.phaseTitle.textContent='Paso 3 · Maniobra';els.orderTitle.textContent=selectedTo?'Movimiento preparado':selectedFrom?'Elige el destino':'Fortifica o pasa';els.orderText.textContent='Mueve tropas por una ruta propia continua o pasa.';els.turnStatus.innerHTML='<strong>Opcional:</strong> un movimiento máximo.';els.phaseBtn.textContent='Pasar maniobra → cierre';if(selectedFrom){els.selection.innerHTML=`<div class="selection-item"><span>Origen · ${tById(selectedFrom).name}</span><strong>${state.territories[selectedFrom].troops} tropas</strong></div>`}if(selectedTo)renderFortifyControls()}
  else{els.phaseTitle.textContent='Paso 4 · Cierre';els.orderTitle.textContent=state.conqueredThisTurn?'Has ganado una carta':'Cierre sin carta';els.orderText.textContent=state.conqueredThisTurn?'Conquistaste: robarás 1 carta.':'No conquistaste en este turno.';els.turnStatus.innerHTML=`<strong>Resumen:</strong> combate resuelto · maniobra resuelta · ${state.conqueredThisTurn?'1 carta pendiente':'0 cartas'}.`;els.phaseBtn.textContent=state.conqueredThisTurn?'Robar carta y pasar →':'Pasar al siguiente jugador →'}
}
function renderAttackControls(){const a=state.territories[selectedFrom],d=state.territories[selectedTo],max=Math.min(3,a.troops-1);selectedDice=Math.min(selectedDice,max);els.selection.innerHTML=`<div class="selection-item"><span>Atacante · ${tById(selectedFrom).name}</span><strong>${a.troops} · ${state.rulesMode==='terrain'?UNIT_TYPES[a.unitType].name:''}</strong></div><div class="selection-item"><span>Defensor · ${tById(selectedTo).name}</span><strong>${d.troops} · ${state.rulesMode==='terrain'?UNIT_TYPES[d.unitType].name:''}</strong></div>`;els.controls.innerHTML=`<label>Dados del atacante (máximo ${max})</label><div class="dice-choice">${[1,2,3].filter(n=>n<=max).map(n=>`<button data-dice="${n}" class="${n===selectedDice?'active':''}">${n} dado${n>1?'s':''}</button>`).join('')}</div>${bonusPreview(selectedFrom,selectedTo)}<button class="primary-btn" id="rollBtn">🎲 Lanzar una ronda</button><button class="secondary-btn" id="blitzBtn">Ataque rápido</button>`;document.querySelectorAll('[data-dice]').forEach(b=>b.onclick=()=>{selectedDice=+b.dataset.dice;renderPanel()});$('#rollBtn').onclick=()=>doAttack(false);$('#blitzBtn').onclick=()=>doAttack(true)}
function renderFortifyControls(){const max=state.territories[selectedFrom].troops-1;if(max<1)return;els.selection.innerHTML+=`<div class="selection-item"><span>Destino · ${tById(selectedTo).name}</span><strong>${state.territories[selectedTo].troops}</strong></div>`;els.controls.innerHTML=`<label>Tropas a mover: <strong id="moveVal">1</strong><input id="moveRange" type="range" min="1" max="${max}" value="1"></label><button class="primary-btn" id="moveBtn">Confirmar movimiento → cierre</button>`;$('#moveRange').oninput=e=>$('#moveVal').textContent=e.target.value;$('#moveBtn').onclick=()=>{if(fortify(state,selectedFrom,selectedTo,+$('#moveRange').value)){selectedFrom=selectedTo=null;render()}else showToast('No existe una ruta propia continua')}}

function territoryClick(id,shift=false){if(!state||aiBusy||rolling||state.winner!==null||!state.players[state.current].human)return;const d=state.territories[id];if(state.phase==='reinforce'){if(state.players[state.current].cards>=5)return showToast('Debes canjear cartas primero');if(d.owner!==state.current)return showToast('Elige uno de tus territorios luminosos');placeTroops(state,id,Math.min(shift?5:1,state.pendingReinforcements),selectedUnit);render();return}if(state.phase==='attack'){if(d.owner===state.current){if(d.troops<2)return showToast('Necesitas al menos 2 tropas');if(!enemiesOf(state,id).length)return showToast('No limita con enemigos');selectedFrom=id;selectedTo=null;selectedDice=Math.min(3,d.troops-1);render();return}if(selectedFrom&&enemiesOf(state,selectedFrom).includes(id)){selectedTo=id;render();return}showToast(selectedFrom?'El objetivo debe estar unido por una ruta iluminada':'Primero elige el origen')}else if(state.phase==='fortify'){if(d.owner!==state.current)return showToast('Solo puedes maniobrar entre territorios propios');if(!selectedFrom){if(d.troops<2)return showToast('El origen necesita 2 tropas');selectedFrom=id}else if(id===selectedFrom){selectedFrom=null;selectedTo=null}else selectedTo=id;render()}}
function diceMarkup(values,raw=[]){return values.map((v,i)=>`<i class="big-die">${v}${raw[i]!==undefined&&v>raw[i]?'<small>+1</small>':''}</i>`).join('')}
function comparisonMarkup(r){return Array.from({length:Math.min(r.attackerDice.length,r.defenderDice.length)},(_,i)=>{const a=r.attackerDice[i],d=r.defenderDice[i],win=a>d;return`<div class="compare-row"><span>🎲 ${a}</span><b>${win?'vence a':'pierde ante'}</b><span>${d} 🎲</span><em>−1 ${win?'defensor':'atacante'}${a===d?' (empate)':''}</em></div>`}).join('')}
async function playAttackApproach(from,to){
  const origin=tById(from),target=tById(to);
  if(!origin||!target)return;
  const x1=origin.x*10,y1=origin.y*8,x2=target.x*10,y2=target.y*8;
  const dx=x2-x1,dy=y2-y1,length=Math.hypot(dx,dy)||1,ux=dx/length,uy=dy/length;
  const midX=(x1+x2)/2,midY=(y1+y2)/2;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const svgNS='http://www.w3.org/2000/svg',layer=document.createElementNS(svgNS,'g');
  layer.classList.add('attack-march');layer.setAttribute('aria-hidden','true');
  layer.innerHTML=`<line class="attack-route" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/><circle class="clash-ring" cx="${midX}" cy="${midY}" r="8"/><g class="marchers attacker"/><g class="marchers defender"/>`;
  const figures=`<g transform="translate(-14 2)"><circle cy="-10" r="4"/><path d="M-5-4h10l3 13H-8zM-4 8l-2 8m10-8 2 8"/></g><g transform="translate(0 -4)"><circle cy="-10" r="4"/><path d="M-5-4h10l3 13H-8zM-4 8l-2 8m10-8 2 8"/></g><g transform="translate(14 2)"><circle cy="-10" r="4"/><path d="M-5-4h10l3 13H-8zM-4 8l-2 8m10-8 2 8"/></g>`;
  const attacker=layer.querySelector('.attacker'),defender=layer.querySelector('.defender');
  attacker.innerHTML=figures;defender.innerHTML=figures;
  attacker.style.setProperty('--march-color',state.players[state.territories[from].owner].color);
  defender.style.setProperty('--march-color',state.players[state.territories[to].owner].color);
  els.map.append(layer);
  const duration=reduced?100:850;
  await new Promise(resolve=>{
    let start;
    function frame(now){
      start??=now;
      const t=Math.min(1,(now-start)/duration),ease=t*t*(3-2*t);
      const ax=x1+(midX-ux*16-x1)*ease,ay=y1+(midY-uy*16-y1)*ease;
      const bx=x2+(midX+ux*16-x2)*ease,by=y2+(midY+uy*16-y2)*ease;
      attacker.setAttribute('transform',`translate(${ax} ${ay})`);
      defender.setAttribute('transform',`translate(${bx} ${by})`);
      if(t<1)requestAnimationFrame(frame);else resolve();
    }
    requestAnimationFrame(frame);
  });
  layer.classList.add('impact');
  await new Promise(resolve=>setTimeout(resolve,reduced?90:330));
  layer.remove();
}
async function doAttack(fast){if(rolling)return;rolling=true;const from=selectedFrom,to=selectedTo,max=fast?Math.min(3,state.territories[from].troops-1):selectedDice,def=Math.min(2,state.territories[to].troops);await playAttackApproach(from,to);els.diceModal.classList.remove('hidden');$('#diceTitle').textContent='Los dados están rodando…';$('#battleRoute').textContent=`${tById(from).name} ataca ${tById(to).name}`;$('#comparison').innerHTML='';$('#closeDice').classList.remove('visible');let fa=Array(max).fill(1),fd=Array(def).fill(1);const draw=()=>{$('#attackerDice').innerHTML=fa.map(v=>`<i class="big-die rolling">${v}</i>`).join('');$('#defenderDice').innerHTML=fd.map(v=>`<i class="big-die rolling">${v}</i>`).join('')};draw();const ticker=setInterval(()=>{fa=fa.map(()=>1+Math.floor(Math.random()*6));fd=fd.map(()=>1+Math.floor(Math.random()*6));draw()},105);await new Promise(r=>setTimeout(r,950));clearInterval(ticker);const result=fast?blitz(state,from,to):attackRound(state,from,to,selectedDice),r=fast?result.rounds.at(-1):result;if(!result.ok||!r){els.diceModal.classList.add('hidden');rolling=false;return}$('#attackerDice').innerHTML=diceMarkup(r.attackerDice,r.rawAttackerDice);$('#defenderDice').innerHTML=diceMarkup(r.defenderDice,r.rawDefenderDice);const al=fast?result.rounds.reduce((s,x)=>s+x.attackerLosses,0):r.attackerLosses,dl=fast?result.rounds.reduce((s,x)=>s+x.defenderLosses,0):r.defenderLosses,bonus=state.rulesMode==='terrain'?`<div class="bonus-note">${r.bonus.attacker?`Atacante +1: ${r.bonus.attackerReasons.join(', ')}.`:'Atacante sin bono.'} ${r.bonus.defender?`Defensor +1: ${r.bonus.defenderReasons.join(', ')}.`:'Defensor sin bono.'}</div>`:'';$('#diceTitle').textContent=r.conquered?'¡Territorio conquistado!':'Resultado de la tirada';$('#comparison').innerHTML=`${bonus}${comparisonMarkup(r)}<div class="battle-summary"><strong>${fast?`${result.rounds.length} rondas. `:''}Pérdidas:</strong> ${al} atacante · ${dl} defensor.${r.conquered?' El territorio cambia de dueño.':' Puedes seguir o retirarte.'}</div>`;$('#closeDice').classList.add('visible');if(r.conquered){selectedFrom=to;selectedTo=null}else if(state.territories[from].troops<2){selectedFrom=selectedTo=null}render();rolling=false}

function showAiSummary(report){return new Promise(resolve=>{clearTimeout(aiTimer);aiResolve=resolve;$('#aiTitle').textContent=`Turno de ${report.playerName}`;const battles=report.battles.slice(-4).map(b=>`<div class="ai-battle"><span>${b.from} → ${b.to}${b.conquered?' · conquistado':''}</span><span>${b.rounds} tirada${b.rounds===1?'':'s'} · pérdidas ${b.attackerLosses}/${b.defenderLosses}</span></div>`).join('');$('#aiSummary').innerHTML=`<div class="ai-kpis"><div class="ai-kpi"><strong>${report.reinforcements}</strong><span>REFUERZOS</span></div><div class="ai-kpi"><strong>${report.battles.length}</strong><span>ATAQUES</span></div><div class="ai-kpi"><strong>${report.conquests}</strong><span>CONQUISTAS</span></div></div>${battles||'<div class="battle-summary">No encontró un ataque favorable este turno.</div>'}${report.eliminated.length?`<div class="battle-summary">Eliminó a ${report.eliminated.join(', ')}.</div>`:''}`;els.aiModal.classList.remove('hidden');aiTimer=setTimeout(closeAiSummary,4200)})}
function closeAiSummary(){clearTimeout(aiTimer);els.aiModal.classList.add('hidden');if(aiResolve){const r=aiResolve;aiResolve=null;r()}}
$('#closeAi').onclick=closeAiSummary;$('#closeDice').onclick=()=>{els.diceModal.classList.add('hidden');render()};els.routesBtn.onclick=()=>{routesAll=!routesAll;updateConnections()};
els.phaseBtn.onclick=()=>{if(!state||rolling)return;if(state.phase==='gameover'){openStart();return}if(state.phase==='attack'){if(!setPhase(state,'fortify'))return showToast('Debes combatir al menos una vez');selectedFrom=selectedTo=null;render()}else if(state.phase==='fortify'){setPhase(state,'close');selectedFrom=selectedTo=null;render()}else if(state.phase==='close'){const earned=state.conqueredThisTurn;endTurn(state);selectedFrom=selectedTo=null;render();if(earned)showToast('Carta robada');runAiTurns()}};
async function runAiTurns(){if(!state||state.winner!==null||state.players[state.current].human)return;aiBusy=true;while(state.winner===null&&!state.players[state.current].human){render();await new Promise(r=>setTimeout(r,650));const report=aiTurn(state,state.current,difficulty);render();if(report.ok)await showAiSummary(report)}aiBusy=false;render()}
function chosen(name){return document.querySelector(`input[name="${name}"]:checked`)?.value}
function startNew(){state=createGame({players:+$('#playerCount').value,seed:Date.now(),human:true,mapId:chosen('mapChoice'),rulesMode:chosen('rulesMode')});difficulty=$('#difficulty').value;selectedFrom=selectedTo=null;selectedUnit='infantry';initMap(state.mapId);els.startModal.classList.add('hidden');render();showToast('Paso 1: coloca tus refuerzos')}
function openStart(){els.startModal.classList.remove('hidden');$('#continueBtn').hidden=!localStorage.getItem(SAVE)}
document.querySelectorAll('.option-card input').forEach(input=>input.onchange=()=>{document.querySelectorAll(`input[name="${input.name}"]`).forEach(x=>x.closest('.option-card').classList.toggle('active',x.checked))});$('#startBtn').onclick=startNew;$('#continueBtn').onclick=()=>{if(load()){initMap(state.mapId);els.startModal.classList.add('hidden');render();runAiTurns()}};$('#newBtn').onclick=openStart;$('#helpBtn').onclick=()=>els.helpModal.classList.remove('hidden');$('#closeHelp').onclick=$('#gotItBtn').onclick=()=>els.helpModal.classList.add('hidden');window.addEventListener('beforeunload',save);

function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;try{c.registerTool({name:'get_campaign_state',title:'Consultar campaña',description:'Devuelve mapa, reglas, turno, fase y jugadores.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>state?{map:getMap(state).name,mode:state.rulesMode,turn:state.turn,phase:state.phase,currentPlayer:state.players[state.current].name,winner:state.winner===null?null:state.players[state.winner].name}:{status:'no_game'}})}catch(e){console.warn('WebMCP no disponible',e)}}
initMap('frontier');if(localStorage.getItem(SAVE))$('#continueBtn').hidden=false;registerWebMCP();
